// Build the header row + string matrix. The workflow now OWNS the schema:
// it writes exactly the columns it can fill, so headers come from the query.
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => Object.keys(r).length > 0);

const toText = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

if (rows.length === 0) {
  return [{ json: { row_count: 0, column_count: 0, columns: [], records: [], snapshot_date: '' } }];
}

const columns = [];
for (const r of rows) for (const k of Object.keys(r)) if (!columns.includes(k)) columns.push(k);

const seen = new Set();
const records = [];
const teams = new Set();
const managers = new Set();
for (const r of rows) {
  const id = toText(r['Employee ID']);
  if (id !== '' && seen.has(id)) continue;
  seen.add(id);
  records.push(columns.map((c) => toText(r[c])));
  if (toText(r['Team']) !== '') teams.add(toText(r['Team']));
  if (toText(r["Manager's Name"]) !== '') managers.add(toText(r["Manager's Name"]));
}

return [{ json: {
  row_count: records.length,
  column_count: columns.length,
  columns,
  records,
  teams_present: [...teams].sort(),
  manager_count: managers.size,
  snapshot_date: toText(rows[0]['Snapshot Date']),
} }];

// Locate workgroup 12056 in the three-level hierarchy this table exposes.
const ROOT = '12056';
const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length > 0);
const L = [];
L.push('FRONTLINE ROSTER REFRESH ABORTED - the query returned zero rows.');
L.push('The Google Sheet was NOT cleared. Its previous contents are intact.');
L.push('');

if (rows.length === 0) {
  L.push("DIAGNOSIS: no active 'Day' rows in the last 30 days at all.");
  L.push('Check that the upstream pipeline is still loading this table.');
} else {
  const atGp = rows.filter((r) => String(r.gp_id) === ROOT);
  const atP  = rows.filter((r) => String(r.p_id) === ROOT);
  const atWg = rows.filter((r) => String(r.wg_id) === ROOT);
  const hits = atGp.length + atP.length + atWg.length;

  if (hits === 0) {
    L.push(`DIAGNOSIS: workgroup ${ROOT} does NOT appear at any of the three`);
    L.push('hierarchy levels this table exposes (wgid, parentwgid, grandparentwgid).');
    L.push('');
    L.push('That means Frontline teams sit MORE than two levels below 12056, so it');
    L.push('is unreachable here - exactly the depth limit noted in the SQL.');
    L.push('');
    L.push('FIX: pick an id from the hierarchy below that sits within two levels of');
    L.push("the teams you want, or revert to  AND t.team IN ('Frontline')  which is");
    L.push('verified to return 20,599 active rows.');
  } else {
    L.push(`Workgroup ${ROOT} DOES appear: ${atWg.length} as wgid, ${atP.length} as parent, ${atGp.length} as grandparent.`);
    L.push('So the scope id is valid and something else filtered everything out -');
    L.push('most likely the employee identity key. Send this output back.');
  }
  L.push('');
  L.push('Three-level hierarchy on the newest active snapshot (gp_id | gp_name | p_id | p_name | wg_id | wg_name | rows):');
  L.push('');
  for (const r of rows.slice(0, 50)) {
    const mark = [r.gp_id, r.p_id, r.wg_id].map(String).includes(ROOT) ? ' <== ' + ROOT : '';
    L.push(`  ${r.gp_id} | ${r.gp_name} | ${r.p_id} | ${r.p_name} | ${r.wg_id} | ${r.wg_name} | ${r.row_count}${mark}`);
  }
}
return [{ json: { diagnosis: L.join('\n') } }];

// One values:batchUpdate body per chunk. Header row is row 1 of the payload.
const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;

const source = $('Code - Normalize Roster').first().json;
const allRows = [source.columns || [], ...(source.records || [])];
const chunks = [];

for (let offset = 0; offset < allRows.length; offset += CHUNK_ROWS) {
  const slice = allRows.slice(offset, offset + CHUNK_ROWS);
  const startRow = offset + 1;
  chunks.push({
    chunk_index: chunks.length + 1,
    chunk_rows: slice.length,
    start_row: startRow,
    request_body: {
      valueInputOption: 'RAW',
      data: [{ range: `${TAB_NAME}!A${startRow}`, majorDimension: 'ROWS', values: slice }],
    },
  });
}
return chunks.map((c) => ({ json: { ...c, chunk_total: chunks.length } }));
